import{_ as e}from"./chunks/image12.BRgDBKom.js";import{_ as o,o as n,c as a,am as i}from"./chunks/framework.CenUaW7a.js";const r="/projects/AiMechaM1/en/advanced-kit/assets/image1.DzC9CDZo.webp",s="/projects/AiMechaM1/en/advanced-kit/assets/image2.BhDqLrnN.png",l="/projects/AiMechaM1/en/advanced-kit/assets/image3.CtJ42QLw.png",c="/projects/AiMechaM1/en/advanced-kit/assets/image4.CddZmMDh.png",g="/projects/AiMechaM1/en/advanced-kit/assets/image5.DGpeyj0l.png",p="/projects/AiMechaM1/en/advanced-kit/assets/image6.CqR3oXJI.png",d="/projects/AiMechaM1/en/advanced-kit/assets/image7.HMgg3JS3.png",h="/projects/AiMechaM1/en/advanced-kit/assets/image8.DbvNEe1c.png",m="/projects/AiMechaM1/en/advanced-kit/assets/image9.DAGxBFaN.png",u="/projects/AiMechaM1/en/advanced-kit/assets/image10.C4cuXFQA.png",D=JSON.parse('{"title":"3.26 Lesson 26: Garbage Sorting and Handling","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.26 Lesson 26 Garbage Sorting and Handling.md","filePath":"docs/3. Course materials/3.26 Lesson 26 Garbage Sorting and Handling.md"}'),b={name:"docs/3. Course materials/3.26 Lesson 26 Garbage Sorting and Handling.md"};function f(y,t,w,v,_,x){return n(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="_3-26-lesson-26-garbage-sorting-and-handling" tabindex="-1">3.26 Lesson 26: Garbage Sorting and Handling <a class="header-anchor" href="#_3-26-lesson-26-garbage-sorting-and-handling" aria-label="Permalink to &quot;3.26 Lesson 26: Garbage Sorting and Handling&quot;">​</a></h1><h2 id="_3-26-1-lesson-introduction" tabindex="-1">3.26.1 Lesson Introduction <a class="header-anchor" href="#_3-26-1-lesson-introduction" aria-label="Permalink to &quot;3.26.1 Lesson Introduction&quot;">​</a></h2><p>Focusing on K230 garbage sorting detection, this lesson combines the robotic arm to achieve intelligent waste sorting and handling. Starting from the importance of environmental protection and comparing manual sorting with AI sorting, this section covers the principles of garbage detection by extracting color, texture, and shape features to match four waste categories. Two progressive tasks are featured: a basic task that illuminates corresponding indicator lights upon recognizing waste, and an advanced task that completes the full workflow of recognition → grasping → transport → disposal. Integrating the vision module, robotic arm, and Mecanum-wheel car for the first time, this lesson introduces function encapsulation to advance modular programming, synthesizes previous knowledge into a complete intelligent robotics workflow, and lays the foundation for advanced large model applications.</p><h2 id="_3-26-2-learning-objectives" tabindex="-1">3.26.2 Learning Objectives <a class="header-anchor" href="#_3-26-2-learning-objectives" aria-label="Permalink to &quot;3.26.2 Learning Objectives&quot;">​</a></h2><p><strong>1.</strong> Understand the technical principles of garbage sorting detection, master the four major waste sorting standards, learn the role of deep learning feature extraction in classification tasks, and comprehend the full-process perception-decision-execution architecture of intelligent sorting systems.</p><p><strong>2.</strong> Launch the garbage sorting mode on the K226 module and verify its functionality. Proficiently master programming commands related to garbage sorting detection and write custom functions for robotic arm actions.</p><p><strong>3.</strong> Establish system integration thinking to understand systems engineering methodologies for multi-module collaboration. Cultivate modular programming mindsets by using functions to encapsulate repetitive actions.</p><p><strong>4.</strong> Connect smart trash cans, waste sorting robots, community smart recycling stations, and environmental big data management to real-world application scenarios, understanding the value of AI technology in environmental protection and sustainable development.</p><h2 id="_3-26-3-preparation" tabindex="-1">3.26.3 Preparation <a class="header-anchor" href="#_3-26-3-preparation" aria-label="Permalink to &quot;3.26.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation</strong>:</p><ul><li>AiMecha M1 Mecanum-Wheel Car Advanced Kit</li><li>Type-C data cable</li><li>Computer × 1</li><li>Remote controller</li></ul><p><strong>Software Preparation</strong>:</p><ul><li>WonderLab graphical programming software</li></ul><p><strong>Four Waste Categories Standards</strong>:</p><ul><li><p><strong>Recyclables</strong>: Household waste suitable for recycling and resource recovery, such as paper, plastic bottles, glass bottles, metals, and old clothing.</p></li><li><p><strong>Kitchen Waste</strong>: Perishable biomass waste, such as leftovers, fruit peels, vegetable leaves, bones, and eggshells.</p></li><li><p><strong>Hazardous Waste</strong>: Waste posing direct or potential hazards to human health or the natural environment, such as batteries, fluorescent tubes, expired medicines, and paint.</p></li><li><p><strong>Other Waste</strong>: Household waste outside the three categories above, such as cigarette butts, ceramics, tissue paper, and dust.</p></li></ul><p><strong>Wiring Instructions</strong>:</p><ul><li><p>Connect the K226 screen module to <strong>port A</strong> of the controller.</p></li><li><p>Connect the three bus servos in series to bus ports S1 or S2, where ID 1 = gripper, ID 2 = forearm, and ID 3 = upper arm.</p></li><li><p>Connect the RGB LEDs to the corresponding lighting effect ports.</p></li><li><p>Connect the buzzer to the buzzer port.</p></li></ul><p><strong>Menu Navigation Path</strong>:</p><ul><li>Recognition Mode → AI Application → Garbage Sorting.</li></ul><p><strong>Robotic Arm Key Positional Parameters</strong>:</p><ul><li><p><strong>Raised Position</strong>: Set Servo ID 2 to 500 and Servo ID 3 to 500 to place the robotic arm in a lifted transport state.</p></li><li><p><strong>Lowered Position</strong>: Set Servo ID 2 to 900 and Servo ID 3 to 200 to place the robotic arm in a lowered grasping state.</p></li><li><p><strong>Gripper Open</strong>: Set Servo ID 1 to position 900 with a running time of 500 ms.</p></li><li><p><strong>Gripper Closed</strong>: Set Servo ID 1 to position 200 with a running time of 500 ms.</p></li></ul><p><strong>Function Encapsulation Description</strong>:</p><ul><li><p><code>Arm Raise</code> function: Encapsulate Servo ID 2 at 500 + Servo ID 3 at 500 into a single function for convenient calling.</p></li><li><p><code>Arm Lower</code> function: Encapsulate Servo ID 2 at 900 + Servo ID 3 at 200 into a single function for convenient calling.</p></li><li><p>Function-based modular programming keeps the main program concise and reduces errors in repetitive code.</p></li></ul><h2 id="_3-26-4-hands-on-project" tabindex="-1">3.26.4 Hands-On Project <a class="header-anchor" href="#_3-26-4-hands-on-project" aria-label="Permalink to &quot;3.26.4 Hands-On Project&quot;">​</a></h2><p><strong>1. Program Logic</strong></p><p>This project builds an intelligent garbage sorting and handling system that coordinates visual perception + mechanical manipulation + motion navigation. The K226 recognizes garbage cards, outputs categories and coordinates, and selects the central target. The decision-making layer schedules tasks by waste category to trigger the workflow of recognition → grasping → transport → disposal → reset. The execution layer coordinates robotic arm grasping and placement, a 2.9 s in-place left turn for car navigation, and audio-visual status feedback. Encapsulating robotic arm actions into functions reproduces an industrial sorting pipeline: visual classification → robotic arm grasping → sorted disposal → standby, establishing a holistic understanding of robotics system integration.</p><img loading="lazy" height="540" width="960" src="'+r+'" class="common_img" style="width:600px;aspect-ratio:960 / 540;"><p>💡<strong>Complete Program Preview:</strong></p><img loading="lazy" height="790" width="878" src="'+s+'" class="common_img" style="width:600px;aspect-ratio:878 / 790;"><p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Presence detection</td><td style="text-align:center;"><img loading="lazy" height="77" width="393" src="'+l+'" class="common_img" style="width:180px;aspect-ratio:393 / 77;"></td><td style="text-align:left;">Determines whether any garbage card is present in the frame and returns a boolean value.</td></tr><tr><td style="text-align:center;">Quantity counting</td><td style="text-align:center;"><img loading="lazy" height="62" width="396" src="'+c+'" class="common_img" style="width:200px;aspect-ratio:396 / 62;"></td><td style="text-align:left;">Counts the number of garbage cards detected in the frame.</td></tr><tr><td style="text-align:center;">Name retrieval</td><td style="text-align:center;"><img loading="lazy" height="53" width="650" src="'+g+'" class="common_img" style="width:300px;aspect-ratio:650 / 53;"></td><td style="text-align:left;">Reads the specific item name of the garbage closest to the center, such as banana peel or toothbrush.</td></tr><tr><td style="text-align:center;">Text parameters</td><td style="text-align:center;"><img loading="lazy" height="55" width="399" src="'+p+'" class="common_img" style="width:240px;aspect-ratio:399 / 55;"></td><td style="text-align:left;">Reads text information indicating the waste category.</td></tr><tr><td style="text-align:center;">Coordinate parameters</td><td style="text-align:center;"><img loading="lazy" height="47" width="592" src="'+d+'" class="common_img" style="width:400px;aspect-ratio:592 / 47;"></td><td style="text-align:left;">Reads the bounding box coordinates of the detected garbage for positional evaluation.</td></tr><tr><td style="text-align:center;">Function definition</td><td style="text-align:center;"><img loading="lazy" height="273" width="337" src="'+h+'" class="common_img" style="width:230px;aspect-ratio:337 / 273;"></td><td style="text-align:left;">Defines custom functions encapsulating robotic arm actions for modular programming.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task 1 Basic Version: Recognizing Different Garbage and Illuminating Corresponding Colored Lights</strong></p><ul><li><p>Initialization settings: At startup, initialize port A, set the running mode to garbage sorting, start detection, turn off the onboard RGB LEDs, and turn off all ultrasonic sensor RGB lights.</p></li><li><p>Main loop structure: Execute <code>Update and save result data</code> as the first step inside the repeat forever loop to synchronize the latest garbage sorting detection data.</p></li><li><p>Toothbrush branch: If <code>Get the garbage name near the center as toothbrush </code>, set all ultrasonic sensor RGB lights to green, and set the onboard RGB LED color to green to indicate recyclables.</p></li><li><p>Battery branch: If <code>Get the garbage name near the center as storage battery</code>, set all ultrasonic sensor RGB lights to gray, and set the onboard RGB LED color to gray to indicate hazardous waste.</p></li><li><p>Expansion branches: Add branches for additional waste items, such as illuminating yellow lights for banana peels representing kitchen waste and red lights for cigarette butts representing other waste.</p></li><li><p>Program outcome: Match different garbage cards to distinct indicator light colors to display sorting results intuitively.</p></li></ul><img loading="lazy" height="852" width="527" src="'+m+'" class="common_img" style="width:460px;aspect-ratio:527 / 852;"><p><strong>Task 2 Advanced Version: Full Workflow of Intelligent Classified Handling</strong></p><ul><li><p>Function definition 1: Define the <code>Robotic Arm Lift Up</code> function by setting bus servo ID 2 to position 500 for 500 ms and bus servo ID 3 to position 500 for 500 ms for the lifted posture.</p></li><li><p>Function definition 2: Define the <code>Robotic Arm Lift Down</code> function by setting bus servo ID 2 to position 900 for 500 ms and bus servo ID 3 to position 260 for 500 ms for the lowered posture.</p></li><li><p>Initialization settings: Reset all three servos to their initial positions, with the robotic arm defaulting to the raised state.</p></li><li><p>Recognition trigger: Initiate the handling sequence when the main loop detects a toothbrush representing recyclable waste.</p></li><li><p>Grasping stage: Set bus servo ID 1 to position 900 to open the gripper → call the <code>Robotic Arm Lift Down</code> function → wait 1 s to stabilize, set bus servo ID 1 to position 260 to clamp the object → play note C2 to signal a successful grasp.</p></li><li><p>Transport stage: Wait 1 s, call the <code>Robotic Arm Lift Up</code> function to lift the object → spin the Mecanum-wheel car left in place at 26% power → wait 2.9 s to face the sorting zone.</p></li><li><p>Disposal stage: Set bus servo ID 1 to position 900 to release the object → stop the Mecanum-wheel car to complete disposal.</p></li><li><p>Reset and wait: Complete the single handling cycle and wait for the next garbage recognition event.</p></li></ul><img loading="lazy" height="630" width="959" src="'+u+'" class="common_img" style="width:700px;aspect-ratio:959 / 630;"><p><strong>Program Design Key Points</strong></p><ul><li><p>Function encapsulation: Encapsulate arm raising and lowering into functions to keep the main program concise and allow parameter adjustments directly within each function.</p></li><li><p>Timing control: Insert wait intervals between actions to ensure each movement completes before the next begins, preventing mechanical conflicts.</p></li><li><p>Gripper timing: Lower the arm into position before closing the gripper, and open the gripper before raising the arm to avoid knocking over the target object.</p></li><li><p>Steering angle: Spin left in place for 2.9 s to achieve an approximate 180° turn, and adjust the duration according to the actual sorting zone layout.</p></li><li><p>Sound-light feedback: Use the buzzer to signal successful grasping and lights to indicate the waste category for intuitive interaction feedback.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1qESIR7n_mxv3oQTrZhNbBTnPKVOk-yT4?usp=sharing" target="_blank" rel="noreferrer">Program Files/Garbage Sorting and Handling</a>.</strong></p></div></li></ul><p><strong>Program Upload:</strong></p><ul><li><p>Step 1: Power on the mecha controller and insert the Type-C data cable into the data port located above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button at the top of the software interface and select the COM port corresponding to CH340 from the port list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to download the compiled program to the mecha controller for execution.</p></li></ul><img loading="lazy" height="508" width="960" src="'+e+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-26-5-expansion-and-advancement" tabindex="-1">3.26.5 Expansion and Advancement <a class="header-anchor" href="#_3-26-5-expansion-and-advancement" aria-label="Permalink to &quot;3.26.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Expansion Project 1: Four-Category Fully Automated Sorting System</strong></p><p>Expand sorting to cover all four waste categories: recyclables → turn left to the green zone, kitchen waste → move forward to the yellow zone, hazardous waste → turn right to the red zone, other waste → reverse to the gray zone. Set up four disposal zones and program the car to automatically recognize waste types and transport them to their corresponding zones for a complete four-category sorting system. Simulate an automated sorting line in a waste treatment plant to understand how AI improves waste sorting efficiency and supports environmental sustainability.</p><p><strong>Expansion Project 2: Multi-Garbage Continuous Sorting Assembly Line</strong></p><p>Design a continuous operation mode: place multiple garbage cards in front of the car so that it recognizes, grasps, transports, and disposes of one item before automatically returning to its starting position to process the next in a loop until all items are sorted. Add a counting function to tally each waste category and announce the final sorting totals. Simulate the continuous operation of industrial sorting robots to explore task queuing and cyclic programming patterns.</p><h2 id="_3-26-6-q-a" tabindex="-1">3.26.6 Q&amp;A <a class="header-anchor" href="#_3-26-6-q-a" aria-label="Permalink to &quot;3.26.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: Which programming command sequence illuminates a blue light representing recyclables when the Mecanum-wheel car detects a beverage can card?</strong><br>A. If battery detected, then set RGB LEDs to red.<br> B. If a beverage can is detected, then set RGB LEDs to blue.<br> C. If temperature is greater than 20, then turn on the fan.<br> D. Set the car&#39;s speed to 50.</p><p><strong>Answer B</strong></p><p><strong>Q2: Once the robotic arm clamps a block representing a waste battery to transport and place it into the hazardous waste zone on the map, what additional commands are required besides controlling the robotic arm and gripper?</strong></p><p><strong>Answer</strong>: Add commands directing the robot to <strong>move to the target location</strong> and <strong>open the gripper to release the block</strong>.</p><h2 id="_3-26-7-technical-support-and-discussion" tabindex="-1">3.26.7 Technical Support and Discussion <a class="header-anchor" href="#_3-26-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.26.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',55)])])}const C=o(b,[["render",f]]);export{D as __pageData,C as default};
